fn main() {
    let numbers = [360, 97, 1024, 561, 143, 2003];
    let mut primes_count = 0;
    for &num in &numbers {
        println!("{}", num);
        let (distinct_primes, sum, largest) = find_distinct_primes(num);
        println!("{}", distinct_primes);
        println!("{}", sum);
        println!("{}", largest);
        if is_prime(num) {
            println!("true");
            primes_count += 1;
        } else {
            println!("false");
        }
    }
    println!("{}", primes_count);
}
fn find_distinct_primes(mut num: u64) -> (usize, u64, u64) {
    let mut distinct_primes = Vec::new();
    let mut sum = 0;
    let mut largest = 0;
    for i in 2..=num {
        while num % i == 0 {
            if !distinct_primes.contains(&i) {
                distinct_primes.push(i);
                sum += i;
                largest = i;
            }
            num /= i;
        }
    }
    (distinct_primes.len(), sum, largest)
}
fn is_prime(num: u64) -> bool {
    if num <= 1 {
        return false;
    }
    for i in 2..=((num as f64).sqrt() as u64) {
        if num % i == 0 {
            return false;
        }
    }
    true
}

fn main() {
    let mut ledger_one = 500;
    let mut ledger_two = 300;
    let mut largest_positive_one = 0;
    let mut negative_count_one = 0;
    let mut below_zero_one = false;
    for adjustment in [200, -750, 130, -60, 400] {
        ledger_one += adjustment;
        if adjustment > largest_positive_one {
            largest_positive_one = adjustment;
        }
        if adjustment < 0 {
            negative_count_one += 1;
        }
        if ledger_one < 0 {
            below_zero_one = true;
        }
    }
    let mut largest_positive_two = 0;
    let mut negative_count_two = 0;
    let mut below_zero_two = false;
    for adjustment in [-100, 250, -50, 75] {
        ledger_two += adjustment;
        if adjustment > largest_positive_two {
            largest_positive_two = adjustment;
        }
        if adjustment < 0 {
            negative_count_two += 1;
        }
        if ledger_two < 0 {
            below_zero_two = true;
        }
    }
    println!("ledger-one\n{}\n{}\n{}\n{}", ledger_one, largest_positive_one, negative_count_one, if below_zero_one { "yes" } else { "no" });
    println!("ledger-two\n{}\n{}\n{}\n{}", ledger_two, largest_positive_two, negative_count_two, if below_zero_two { "yes" } else { "no" });
    if ledger_one > ledger_two {
        println!("ledger-one");
    } else {
        println!("ledger-two");
    }
}

